import{I as e,o as p,c as t,b6 as l,J as h,w as r,j as a,a as o}from"./chunks/framework.BUXTSoD9.js";const u=JSON.parse('{"title":"The Mom Test：ユーザーインタビューでニーズを検証する方法","description":"ゼロベースの読者向けの The Mom Test 入門記事。礼儀正しいフィードバックを避け、実際の行動、具体的な事実、既存の問題を中心にユーザーインタビューを行い、「良さそう」をより確実なニーズ判断に変える方法を学びます。","frontmatter":{"title":"The Mom Test：ユーザーインタビューでニーズを検証する方法","description":"ゼロベースの読者向けの The Mom Test 入門記事。礼儀正しいフィードバックを避け、実際の行動、具体的な事実、既存の問題を中心にユーザーインタビューを行い、「良さそう」をより確実なニーズ判断に変える方法を学びます。"},"headers":[],"relativePath":"ja-jp/stage-1/appendix-mom-test/index.md","filePath":"ja-jp/stage-1/appendix-mom-test/index.md"}'),d={name:"ja-jp/stage-1/appendix-mom-test/index.md"},m=Object.assign(d,{setup(c){const i="約 <strong>1.5 時間</strong>";return(b,s)=>{const n=e("ChapterIntroduction");return p(),t("div",null,[s[1]||(s[1]=l('<h1 id="the-mom-test-ユーザーインタビューでニーズを検証する方法" tabindex="-1">The Mom Test：ユーザーインタビューでニーズを検証する方法 <a class="header-anchor" href="#the-mom-test-ユーザーインタビューでニーズを検証する方法" aria-label="Permalink to “The Mom Test：ユーザーインタビューでニーズを検証する方法”">​</a></h1><p><a id="top-mom"></a></p><h2 id="本章のガイド" tabindex="-1">本章のガイド <a class="header-anchor" href="#本章のガイド" aria-label="Permalink to “本章のガイド”">​</a></h2>',3)),h(n,{duration:i,tags:["ユーザーインタビュー","ニーズ検証","ユーザーリサーチ","プロダクト調査"],coreOutput:"1 組のよりリアルな情報を引き出せるインタビュー質問",expectedOutput:"ユーザーの礼儀正しい励ましを検証とみなさず、実際の行動で方向性を判断できる"},{default:r(()=>[...s[0]||(s[0]=[a("p",null,"多くの人が初めてプロダクト調査をする時、最も重要なのは「人に話を聞くこと」だと思いがちです。そこで友達や同僚、さらには家族に聞いてみます：",-1),a("ul",null,[a("li",null,"このアイデア、どう思う？"),a("li",null,"こんなプロダクトがあったら、使う？"),a("li",null,"この機能、悪くないよね？")],-1),a("p",null,"相手もとても励みになるフィードバックをくれるでしょう：",-1),a("ul",null,[a("li",null,"いいね"),a("li",null,"役に立ちそう"),a("li",null,"試してみたらいいと思う")],-1),a("p",null,"問題は、これらの回答は通常、判断に役立たないということです。それはむしろ礼儀、サポート、あるいはその場で盛り上げようとする自然な反応に近いものです。自分が「市場検証」を得たと思っても、実際には判断に使いづらい慰めを集めただけなのです。",-1),a("p",null,[o("The Mom Test という手法は、まさにこの問題を解決するためのものです。それは私たちに注意喚起します："),a("strong",null,"ユーザーがわざと嘘をついているのではなく、あなたの質問の仕方が、自然と相手を聞こえの良いが無難な回答に導いているのです。")],-1)])]),_:1}),s[2]||(s[2]=l(`<div class="info custom-block"><p class="custom-block-title">最小 SOP</p><p><strong>目的</strong>：読み終わった後、ユーザーとどう話せば「良さそう」しか聞けない会話から、方向性を判断できる情報を引き出せるかがより明確になります。</p><p><strong>アクション項目</strong>：本来聞こうとしていた 5 つの質問を書き直し、「最近いつありましたか」「その時どうしましたか」を優先して聞くようにします。</p><p><strong>結果</strong>：どれが意見で、どれが本当に判断を支える証拠なのかを見分けやすくなります。</p><p><strong>キーワードジャンプ</strong>：<a href="#mom-what">The Mom Testとは</a> · <a href="#mom-principles">3つの核心原則</a> · <a href="#mom-ai">AIの活用法</a></p></div><h2 id="この章で学ぶ内容" tabindex="-1">この章で学ぶ内容 <a class="header-anchor" href="#この章で学ぶ内容" aria-label="Permalink to “この章で学ぶ内容”">​</a></h2><ol><li>The Mom Test が一体何を解決しようとしているのか、なぜ多くの「ユーザー調査」が実際にはリアルな情報を調査できていないのか</li><li>この手法の最も核心的ないくつかの原則：意見を聞くのを減らし、行動を聞くのを増やす；仮定を聞くのを減らし、事実を聞くのを増やす</li><li>偽陽性フィードバックを得やすい質問を、より価値のあるインタビュー質問に書き直す方法</li><li>The Mom Test と JTBD、ニーズ検証、MVP 判断をどう組み合わせて使うか</li></ol><p><a id="mom-what"></a></p><h2 id="_1-the-mom-test-とは一体何か" tabindex="-1"><a href="#top-mom">1. The Mom Test とは一体何か</a> <a class="header-anchor" href="#_1-the-mom-test-とは一体何か" aria-label="Permalink to “1. The Mom Test とは一体何か”">​</a></h2><p>The Mom Test は Rob Fitzpatrick の同名の著書に由来します。その名前は冗談のように聞こえますが、非常に的確に指摘しています：</p><p><strong>あなたのお母さんでさえ、「それはダメなアイデアだ」とは直接言えないのです。</strong></p><p>その理由は彼女が不誠実だからではなく：</p><ul><li>あなたを傷つけたくない</li><li>無意識にあなたを励ましたくなる</li><li>あなたの表現に沿って答えやすくなる</li></ul><p>実はお母さんだけではなく、友達、同僚、昔の同級生、さらには多くの見知らぬ人も、あなたのプロダクトアイデアに直面すると、似たような「ポジティブなフィードバック」をよくくれます。これはニーズが本当に存在するという意味ではなく、あなたが質問を誰もが賛同しやすい形にしてしまっているだけです。</p><p>だから The Mom Test のポイントは決して「お母さんに聞くな」ではなく：</p><p><strong>質問を誰もがあなたに同調して答えるような形にしないことです。</strong></p><p>この手法が本当に教えたいのは、対話を通じて、よりリアルなニーズに近い情報を手に入れる方法であり、自分を気分よくさせるコメントを集めることではありません。</p><h2 id="_2-この手法が解決する核心的な問題" tabindex="-1">2. この手法が解決する核心的な問題 <a class="header-anchor" href="#_2-この手法が解決する核心的な問題" aria-label="Permalink to “2. この手法が解決する核心的な問題”">​</a></h2><p>The Mom Test が主に解決するのは、非常に一般的な認知の錯覚です：</p><p><strong>礼儀正しいポジティブなフィードバックを、リアルなニーズと混同してしまう。</strong></p><p>例えばあなたが聞くと：</p><ul><li>この App のアイデア、どう思う？</li><li>AI で履歴書を書くツールがあったら、使う？</li><li>この機能、価値あるでしょ？</li></ul><p>これらの質問に共通する特徴は：</p><ul><li>すべて「意見」を聞いている</li><li>すべて少し暗示を含んでいる</li><li>すべてまだ起きていない未来について話している</li></ul><p>そして「意見」と「未来の仮定」に対する回答は、通常不安定です。多くの人は自分の興味、実行力、将来の購入意欲を過大評価しがちです。</p><p>だから The Mom Test は注意を促します：</p><ul><li>他人のあなたのアイデアに対する評価をあまり信用しない</li><li>他人の未来の行動予測をあまり信用しない</li><li>できるだけユーザーのすでに起こった実際の行動に戻る</li></ul><p>「使うかどうか」よりも「前回どう対処したか」のほうが、真実に近いことが多いからです。</p><p><a id="mom-principles"></a></p><h2 id="_3-3つの最も核心的な原則" tabindex="-1"><a href="#top-mom">3. 3つの最も核心的な原則</a> <a class="header-anchor" href="#_3-3つの最も核心的な原則" aria-label="Permalink to “3. 3つの最も核心的な原則”">​</a></h2><p>最も重要な部分だけを先に覚えたいなら、次の 3 つの原則を先に覚えてください。</p><h3 id="_3-1-自分のアイデアについて話すのを減らし、ユーザーの過去のリアルな体験について話す" tabindex="-1">3.1 自分のアイデアについて話すのを減らし、ユーザーの過去のリアルな体験について話す <a class="header-anchor" href="#_3-1-自分のアイデアについて話すのを減らし、ユーザーの過去のリアルな体験について話す" aria-label="Permalink to “3.1 自分のアイデアについて話すのを減らし、ユーザーの過去のリアルな体験について話す”">​</a></h3><p>多くの無効なインタビューは冒頭で自分のソリューションを語り、自分がどれだけ興奮しているか、どんなプロダクトを作ろうとしているかを話します。問題は、あなたが話しすぎると、相手が「あなたに合わせる」「あなたを励ます」モードに入りやすくなることです。</p><p>それに対して、より良い方法は相手の体験に焦点を当てることです：</p><ul><li>前回この問題に直面したのはいつですか？</li><li>その時何をしていましたか？</li><li>最終的にどう対処しましたか？</li><li>どの手順が一番面倒でしたか？</li></ul><p>この種の質問は、想像上の好みに留まることなく、より自然に会話を現実に引き戻せることに気づくでしょう。</p><h3 id="_3-2-抽象的な意見を聞くのを減らし、具体的な事実を聞く" tabindex="-1">3.2 抽象的な意見を聞くのを減らし、具体的な事実を聞く <a class="header-anchor" href="#_3-2-抽象的な意見を聞くのを減らし、具体的な事実を聞く" aria-label="Permalink to “3.2 抽象的な意見を聞くのを減らし、具体的な事実を聞く”">​</a></h3><p>「この機能は良さそう」「悪くないね」「ちょっと役立ちそうかも」、これらの表現はあまりに抽象的で、プロダクトの判断に役立ちません。</p><p>より価値のある情報は通常、次のようなものです：</p><ul><li>先週この件に 2 時間悩まされました</li><li>今は Excel と WeChat でなんとかやりくりしています</li><li>先月似たようなツールにお金を払いました</li><li>一番怖いのは間違えることではなく、遅くなることです</li></ul><p>これらこそが、問題の強度、頻度、有料化の可能性を判断するのに本当に役立つ情報です。</p><h3 id="_3-3-ユーザーがどんなソリューションを欲しがっているか聞くのを減らし、今どう問題を解決しているか見る" tabindex="-1">3.3 ユーザーがどんなソリューションを欲しがっているか聞くのを減らし、今どう問題を解決しているか見る <a class="header-anchor" href="#_3-3-ユーザーがどんなソリューションを欲しがっているか聞くのを減らし、今どう問題を解決しているか見る" aria-label="Permalink to “3.3 ユーザーがどんなソリューションを欲しがっているか聞くのを減らし、今どう問題を解決しているか見る”">​</a></h3><p>ユーザーは自分の悩みを説明するのは得意ですが、ソリューションを設計するのは必ずしも得意ではありません。</p><p>もし聞くと：</p><ul><li>AI がこれを自動でやってくれる機能、欲しくない？</li><li>スマート機能を追加するのって役立つ？</li></ul><p>得られるのは通常、あるソリューションに対する曖昧な態度だけであり、ニーズそのものではありません。</p><p>より良い質問は：</p><ul><li>今、この問題にどう対処していますか？</li><li>なぜこの方法を選んだのですか？</li><li>どこが良くないですか？</li></ul><p>既存の代替ソリューションを見極めることは、「何を欲しがっているか」を直接聞くよりも重要なことが多いのです。</p><h2 id="_4-なぜ人々はいつも聞こえは良いが役に立たない回答をするのか" tabindex="-1">4. なぜ人々はいつも聞こえは良いが役に立たない回答をするのか <a class="header-anchor" href="#_4-なぜ人々はいつも聞こえは良いが役に立たない回答をするのか" aria-label="Permalink to “4. なぜ人々はいつも聞こえは良いが役に立たない回答をするのか”">​</a></h2><p>これが理解できれば、インタビューでの誤判断が大幅に減ります。</p><h3 id="_4-1-人は無意識に礼儀正しさを保つ" tabindex="-1">4.1 人は無意識に礼儀正しさを保つ <a class="header-anchor" href="#_4-1-人は無意識に礼儀正しさを保つ" aria-label="Permalink to “4.1 人は無意識に礼儀正しさを保つ”">​</a></h3><p>特に会話の相手と関係がある場合、相手は直接言いにくいものです：</p><ul><li>この方向、ちょっと無理そう</li><li>全然使わない</li><li>この問題はそこまで重要じゃない</li></ul><p>むしろ「いいね」「機会があればやってみてもいいかも」と言いがちです。</p><h3 id="_4-2-人は未来の自分を過大評価する" tabindex="-1">4.2 人は未来の自分を過大評価する <a class="header-anchor" href="#_4-2-人は未来の自分を過大評価する" aria-label="Permalink to “4.2 人は未来の自分を過大評価する”">​</a></h3><p>多くの人が心から未来の自分を信じています：</p><ul><li>もっと自律的になる</li><li>もっと学ぶ意欲がある</li><li>もっとお金を払う</li><li>もっと新しいツールを試す</li></ul><p>だから「あればたぶん使う」という言葉は、未来に本当に使うこととイコールではないことが多いのです。</p><h3 id="_4-3-質問の仕方自体が答えを誘導している" tabindex="-1">4.3 質問の仕方自体が答えを誘導している <a class="header-anchor" href="#_4-3-質問の仕方自体が答えを誘導している" aria-label="Permalink to “4.3 質問の仕方自体が答えを誘導している”">​</a></h3><p>あなたが聞くとき：</p><ul><li>このアイデア、いいよね？</li><li>この機能、役に立つでしょ？</li></ul><p>あなたは実はこっそり「正解」を質問に忍ばせているのです。</p><p>これこそが The Mom Test が特に強調している理由です：<strong>インタビューを自分への承認探しにしないこと。</strong></p><h2 id="_5-直接比較-どんな質問が無駄になりやすく、どんな質問がより価値があるか" tabindex="-1">5. 直接比較：どんな質問が無駄になりやすく、どんな質問がより価値があるか <a class="header-anchor" href="#_5-直接比較-どんな質問が無駄になりやすく、どんな質問がより価値があるか" aria-label="Permalink to “5. 直接比較：どんな質問が無駄になりやすく、どんな質問がより価値があるか”">​</a></h2><p>以下の対照表は、ほぼすべての初心者が使うものです。</p><table tabindex="0"><thead><tr><th>無駄になりやすい質問</th><th>より価値のある質問</th></tr></thead><tbody><tr><td>このアイデア、どう思う？</td><td>前回この問題に直面したのはいつ？</td></tr><tr><td>このプロダクトがあったら使う？</td><td>今、この件をどう処理している？</td></tr><tr><td>この機能にお金を払う？</td><td>前回この問題にお金を使った？何に？</td></tr><tr><td>この機能は重要だと思う？</td><td>このプロセスで一番面倒で、一番遅くて、一番不安なのはどの手順？</td></tr><tr><td>AI が自動でやってくれる機能、欲しくない？</td><td>なぜまだもっと使いやすい解決策を見つけられていないの？</td></tr></tbody></table><p>この表で最も重要なのは具体的な文ではなく、背後にある方向性です：</p><ul><li>意見から事実へ</li><li>未来から過去へ</li><li>あなたのソリューションからユーザーの問題へ</li></ul><h2 id="_6-ゼロベースでもすぐに使えるインタビューの流れ" tabindex="-1">6. ゼロベースでもすぐに使えるインタビューの流れ <a class="header-anchor" href="#_6-ゼロベースでもすぐに使えるインタビューの流れ" aria-label="Permalink to “6. ゼロベースでもすぐに使えるインタビューの流れ”">​</a></h2><p>今すぐ誰かに話を聞きに行きたいなら、次の順序で進められます。</p><h3 id="_6-1-オープニング-学習しているのであって、売り込んでいるのではないと伝える" tabindex="-1">6.1 オープニング：学習しているのであって、売り込んでいるのではないと伝える <a class="header-anchor" href="#_6-1-オープニング-学習しているのであって、売り込んでいるのではないと伝える" aria-label="Permalink to “6.1 オープニング：学習しているのであって、売り込んでいるのではないと伝える”">​</a></h3><p>例えば：</p><blockquote><p>最近、皆さんがこの種の問題にどう対処しているかを調べていて、まずリアルな状況を知りたいと思っています。売り込みではありません。</p></blockquote><p>このような表現は、相手が「ポジティブなフィードバックをあげなきゃ」という心理的負担を減らすのに役立ちます。</p><h3 id="_6-2-最近のリアルな体験から聞き始める" tabindex="-1">6.2 最近のリアルな体験から聞き始める <a class="header-anchor" href="#_6-2-最近のリアルな体験から聞き始める" aria-label="Permalink to “6.2 最近のリアルな体験から聞き始める”">​</a></h3><p>まず次のような質問から始められます：</p><ul><li>前回この問題に直面したのはいつですか？</li><li>その時何が起きましたか？</li><li>最初の反応はどう対処しましたか？</li></ul><p>会話が具体的な出来事に入ると、情報の質は通常明らかに向上します。</p><h3 id="_6-3-行動、コスト、代替ソリューションについて掘り下げる" tabindex="-1">6.3 行動、コスト、代替ソリューションについて掘り下げる <a class="header-anchor" href="#_6-3-行動、コスト、代替ソリューションについて掘り下げる" aria-label="Permalink to “6.3 行動、コスト、代替ソリューションについて掘り下げる”">​</a></h3><p>引き続き聞きます：</p><ul><li>今、どうやって解決していますか？</li><li>この方法で一番不満なのは何ですか？</li><li>このためにどれくらいの時間、お金、または労力を費やしましたか？</li><li>他の方法を試したことはありますか？なぜ続けなかったのですか？</li></ul><h3 id="_6-4-最後に痛みの強さと優先度を判断する" tabindex="-1">6.4 最後に痛みの強さと優先度を判断する <a class="header-anchor" href="#_6-4-最後に痛みの強さと優先度を判断する" aria-label="Permalink to “6.4 最後に痛みの強さと優先度を判断する”">​</a></h3><p>「痛いですか」と直接聞く必要はなく、詳細から判断できます：</p><ul><li>よく直面しているか</li><li>すでに自発的に対処しようとしているか</li><li>すでにコストを払う意欲があるか</li><li>この話をしている時に明らかな感情が表れているか</li></ul><p>これらはすべて「これがあなたのペインポイントですか」という一言よりも役立ちます。</p><h2 id="_7-より完全な例" tabindex="-1">7. より完全な例 <a class="header-anchor" href="#_7-より完全な例" aria-label="Permalink to “7. より完全な例”">​</a></h2><p>「AI で大学生の履歴書を添削する」プロダクトを作りたいと仮定しましょう。</p><h3 id="誤った聞き方" tabindex="-1">誤った聞き方 <a class="header-anchor" href="#誤った聞き方" aria-label="Permalink to “誤った聞き方”">​</a></h3><p>同僚に聞きます：</p><blockquote><p>AI 履歴書最適化ツールを作ろうと思うんだけど、どう思う？ もし職種に合わせて自動で履歴書を修正できたら、使う？</p></blockquote><p>この時、相手はこう言う可能性が高いです：</p><ul><li>良さそう</li><li>役に立ちそう</li><li>無料なら試すかも</li></ul><p>これらの回答はニーズがどれほど強いかを判断するのにほとんど役立ちません。</p><h3 id="より良い聞き方" tabindex="-1">より良い聞き方 <a class="header-anchor" href="#より良い聞き方" aria-label="Permalink to “より良い聞き方”">​</a></h3><p>次のように変えられます：</p><blockquote><p>前回履歴書を修正したのはいつ？ その時なぜ修正したの？ どうやって修正したの？ どの手順が一番詰まった？ 誰かに見てもらったことはある？ 履歴書のためににお金や時間をかけたことはある？</p></blockquote><p>これらの質問を通じて、得られる情報は次のようなものかもしれません：</p><ul><li>多くの人は書けないのではなく、異なる職種に合わせて書き換える方法がわからない</li><li>一番痛いのはレイアウトではなく、「どの経歴を書く価値があるか」がわからないこと</li><li>怠けているのではなく、毎回履歴書を修正するのが精神的に消耗するから先延ばしにする</li><li>先輩のアドバイス、テンプレートサイト、AI ツール、友達に見てもらうことでなんとか解決している</li></ul><p>この時点で、本当の問題にずっと近づいています。</p><h2 id="_8-the-mom-test-と-jtbd-をどう組み合わせて使うか" tabindex="-1">8. The Mom Test と JTBD をどう組み合わせて使うか <a class="header-anchor" href="#_8-the-mom-test-と-jtbd-をどう組み合わせて使うか" aria-label="Permalink to “8. The Mom Test と JTBD をどう組み合わせて使うか”">​</a></h2><p>もし JTBD が「ユーザーがどんな進捗を達成したいか」を見極めるのを助けるなら、The Mom Test はむしろこう教えていると言えます：</p><p><strong>インタビューを通じて、この Job が本当に存在するかどうかを確認する方法。</strong></p><p>この二つを繋げて使うことができます：</p><ol><li>まず JTBD で一つの Job を仮定する</li><li>次に The Mom Test の方法で、ユーザーの最近のリアルな体験について聞く</li><li>この Job が本当に高頻度で、リアルで、優先してやる価値があるかを見る</li></ol><p>例えば、JTBD の仮定が次のようだとします：</p><blockquote><p>インターンに応募する準備をする時、古い履歴書を職種に合ったバージョンに素早く書き換えて、できるだけ早く応募を完了したい。</p></blockquote><p>それなら The Mom Test スタイルの質問で検証できます：</p><ul><li>前回応募したのはいつ？</li><li>その時、どうやって履歴書を修正した？</li><li>どの部分が一番書きにくかった？</li><li>修正後、どうやって十分かどうかを判断した？</li></ul><p>このように手法が繋がります：</p><ul><li>JTBD はニーズ仮説の定義に役立つ</li><li>The Mom Test はインタビューによる仮説検証に役立つ</li></ul><h2 id="_9-初心者がユーザーインタビューをする時に最も陥りやすい誤解" tabindex="-1">9. 初心者がユーザーインタビューをする時に最も陥りやすい誤解 <a class="header-anchor" href="#_9-初心者がユーザーインタビューをする時に最も陥りやすい誤解" aria-label="Permalink to “9. 初心者がユーザーインタビューをする時に最も陥りやすい誤解”">​</a></h2><h3 id="_9-1-インタビューをプロダクト紹介会にしてしまう" tabindex="-1">9.1 インタビューをプロダクト紹介会にしてしまう <a class="header-anchor" href="#_9-1-インタビューをプロダクト紹介会にしてしまう" aria-label="Permalink to “9.1 インタビューをプロダクト紹介会にしてしまう”">​</a></h3><p>自分のアイデアを話しすぎると、相手はリアルな状況を教えるのではなく、あなたに合わせ始めやすくなります。</p><h3 id="_9-2-インタビュー相手が全部知り合い" tabindex="-1">9.2 インタビュー相手が全部知り合い <a class="header-anchor" href="#_9-2-インタビュー相手が全部知り合い" aria-label="Permalink to “9.2 インタビュー相手が全部知り合い”">​</a></h3><p>知り合いに聞くのも悪くありませんが、知り合いは励ましてくれやすいです。少なくともリアルなユーザーに近い人も混ぜる必要があり、自分を支持してくれる人だけに聞くべきではありません。</p><h3 id="_9-3-早すぎる機能の追及" tabindex="-1">9.3 早すぎる機能の追及 <a class="header-anchor" href="#_9-3-早すぎる機能の追及" aria-label="Permalink to “9.3 早すぎる機能の追及”">​</a></h3><p>問題をはっきりさせる前に、ボタン、画面、機能の詳細について聞き始めると、通常ソリューションに入るのが早すぎます。</p><h3 id="_9-4-「使います」の一言を検証結果とみなす" tabindex="-1">9.4 「使います」の一言を検証結果とみなす <a class="header-anchor" href="#_9-4-「使います」の一言を検証結果とみなす" aria-label="Permalink to “9.4 「使います」の一言を検証結果とみなす”">​</a></h3><p>インタビューはせいぜい方向性の判断に役立ち、検証が完了したこととイコールではありません。本当の検証は、最終的にユーザーが実際のコスト（時間、切り替えコスト、トライアル行動、さらには有料）を払う意欲があるかどうかにかかっています。</p><h3 id="_9-5-インタビュー終了後に整理しない" tabindex="-1">9.5 インタビュー終了後に整理しない <a class="header-anchor" href="#_9-5-インタビュー終了後に整理しない" aria-label="Permalink to “9.5 インタビュー終了後に整理しない”">​</a></h3><p>聞き終わってそのままにしておくと、情報はすぐに曖昧な印象になってしまいます。できるだけ早く整理しましょう：</p><ul><li>高頻度で出現した問題</li><li>ユーザーの生の言葉の中の感情ワード</li><li>現在の代替ソリューション</li><li>すでに払ったコスト</li><li>自分の新しい判断</li></ul><h2 id="_10-そのままコピーして使える質問リスト" tabindex="-1">10. そのままコピーして使える質問リスト <a class="header-anchor" href="#_10-そのままコピーして使える質問リスト" aria-label="Permalink to “10. そのままコピーして使える質問リスト”">​</a></h2><p>すぐに始めたいなら、ここに汎用性の高い質問セットがあります。</p><h3 id="オープニングの質問" tabindex="-1">オープニングの質問 <a class="header-anchor" href="#オープニングの質問" aria-label="Permalink to “オープニングの質問”">​</a></h3><ul><li>前回この問題に直面したのはいつですか？</li><li>その時具体的に何が起きましたか？</li></ul><h3 id="行動の質問" tabindex="-1">行動の質問 <a class="header-anchor" href="#行動の質問" aria-label="Permalink to “行動の質問”">​</a></h3><ul><li>その時どう対処しましたか？</li><li>なぜこの方法を選んだのですか？</li></ul><h3 id="コストの質問" tabindex="-1">コストの質問 <a class="header-anchor" href="#コストの質問" aria-label="Permalink to “コストの質問”">​</a></h3><ul><li>この件には通常どれくらいの時間や労力がかかりますか？</li><li>この解決のためににお金を使ったことはありますか？</li></ul><h3 id="代替ソリューションの質問" tabindex="-1">代替ソリューションの質問 <a class="header-anchor" href="#代替ソリューションの質問" aria-label="Permalink to “代替ソリューションの質問”">​</a></h3><ul><li>他のツールや方法を試したことはありますか？</li><li>なぜ結局続けなかったのですか？</li></ul><h3 id="締めくくりの質問" tabindex="-1">締めくくりの質問 <a class="header-anchor" href="#締めくくりの質問" aria-label="Permalink to “締めくくりの質問”">​</a></h3><ul><li>将来同じ問題に直面したら、最も理想的な解決方法はどんなものだと思いますか？</li></ul><p>この締めくくりの質問は聞いてもいいですが、最後に置くのが良いでしょう。なぜなら、前半では事実をより多く手に入れる必要があり、願望ではないからです。</p><h2 id="_11-まとめ" tabindex="-1">11. まとめ <a class="header-anchor" href="#_11-まとめ" aria-label="Permalink to “11. まとめ”">​</a></h2><p>The Mom Test の最も重要な貢献は、「よりうまく話す」スキルを与えることではなく、より冷静な判断方法を構築することです：</p><ul><li>他人のあなたのアイデアに対する褒め言葉を急いで信用しない</li><li>「あれば使う」をリアルなニーズとみなさない</li><li>インタビューを自分への承認探しにしない</li></ul><p>本当に価値のあるインタビューは、これらのものにできるだけ戻るべきです：</p><ul><li>ユーザーの最近のリアルな体験</li><li>今どう対処しているか</li><li>すでにどんなコストを払っているか</li><li>どこで明らかに不快感を感じているか</li></ul><p>このように聞き始めると、得られる情報は時に聞こえは良くないかもしれませんが、通常はより役立ちます。 プロダクトを作る時、<strong>役に立つ真実は、聞こえの良い励ましよりも常に重要です。</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-ai-を活用してユーザーインタビューに役立てる方法" tabindex="-1"><a href="#top-mom">12. AI を活用してユーザーインタビューに役立てる方法</a> <a class="header-anchor" href="#_12-ai-を活用してユーザーインタビューに役立てる方法" aria-label="Permalink to “12. AI を活用してユーザーインタビューに役立てる方法”">​</a></h2><p>The Mom Test は本質的に「リアルな人と話す」手法なので、AI が実際のインタビューに代わることはありません。しかし、AI はインタビューの前、中、後でサポートするのに非常に適しており、特に初心者のハードルを下げるのに役立ちます。</p><h3 id="_12-1-ai-に「聞きづらい質問」を書き直させる" tabindex="-1">12.1 AI に「聞きづらい質問」を書き直させる <a class="header-anchor" href="#_12-1-ai-に「聞きづらい質問」を書き直させる" aria-label="Permalink to “12.1 AI に「聞きづらい質問」を書き直させる”">​</a></h3><p>「このアイデア、どう思う？」と聞くべきではないとわかっていても、口を開くとついこの言葉に戻ってしまう人は多いです。まず自分で準備した質問を AI に渡して、書き直してもらうことができます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>以下はユーザーインタビューで聞こうとしている質問です：</span></span>
<span class="line"><span>[質問を貼り付け]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The Mom Test の原則に従って書き直してください：</span></span>
<span class="line"><span>1. 意見型の質問を削除する</span></span>
<span class="line"><span>2. 未来を仮定する質問を削除する</span></span>
<span class="line"><span>3. 過去のリアルな行動、既存の代替ソリューション、すでに払ったコストを中心に質問を書き直す</span></span>
<span class="line"><span>4. 最後にインタビューで直接使える 8〜10 の質問リストに整理する</span></span></code></pre></div><p>初心者っぽい入力でも全く問題ありません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ユーザーに聞きたいことがあります：</span></span>
<span class="line"><span>1. AI で履歴書を添削するツールを作ろうと思うんだけど、どう思う？</span></span>
<span class="line"><span>2. 使う？</span></span>
<span class="line"><span>3. お金払う？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>もっと良い聞き方に書き直して。</span></span></code></pre></div><p>AI が出力する有用な回答は次のようになります：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>書き直した質問：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 前回履歴書を修正したのはいつ？</span></span>
<span class="line"><span>2. その時なぜ修正したの？</span></span>
<span class="line"><span>3. どうやって修正したの？</span></span>
<span class="line"><span>4. どの手順に一番時間がかかった？</span></span>
<span class="line"><span>5. 誰かに見てもらったことはある？</span></span>
<span class="line"><span>6. 履歴書の修正のためににお金や時間をかけたことはある？</span></span></code></pre></div><p>このような出力は、元々「意見を聞く」質問を「リアルな行動を聞く」質問に直接変えてくれるので、非常に役立ちます。</p><h3 id="_12-2-ai-に異なる対象に合わせたインタビューのガイドラインを作成させる" tabindex="-1">12.2 AI に異なる対象に合わせたインタビューのガイドラインを作成させる <a class="header-anchor" href="#_12-2-ai-に異なる対象に合わせたインタビューのガイドラインを作成させる" aria-label="Permalink to “12.2 AI に異なる対象に合わせたインタビューのガイドラインを作成させる”">​</a></h3><p>同じ方向性でも、異なるターゲット層に対してはインタビューの焦点が異なります。例えば学生、人事、フリーランサーでは関心事が全く違います。AI に異なる対象向けにそれぞれのガイドラインを作成させることができます：</p><ul><li>初心者ユーザーには、最近のリアルな体験を重点的に聞く</li><li>ヘビーユーザーには、代替ソリューションと痛みの強さを重点的に聞く</li><li>有料ユーザーには、すでにコストを払ったかどうかを重点的に聞く</li></ul><p>こうすることで、実際に話す時にリズムができ、誰にでも同じ質問を繰り返すことがなくなります。</p><p>例えば次のように入力できます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2種類の人に聞きます：</span></span>
<span class="line"><span>1. 初めてインターンを探す大学生</span></span>
<span class="line"><span>2. たくさんの人の履歴書を見てきた先輩</span></span>
<span class="line"><span></span></span>
<span class="line"><span>それぞれインタビューガイドラインを 6 つずつの質問で作って。</span></span></code></pre></div><p>AI は次のように出力するかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>大学生向け：</span></span>
<span class="line"><span>1. 前回インターンに応募したのはいつ？</span></span>
<span class="line"><span>2. その時一番詰まったのはどの手順？</span></span>
<span class="line"><span>3. 自分の履歴書が応募できるレベルかどうか、どうやって判断する？</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先輩向け：</span></span>
<span class="line"><span>1. 前回誰かの履歴書を見たのはいつ？</span></span>
<span class="line"><span>2. よく見かける明らかな問題は何？</span></span>
<span class="line"><span>3. 後輩が一番詰まるのはどの手順？</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>このようにすれば、ゼロから質問を考える必要がなく、インタビューの準備がずっと楽になります。</p><h3 id="_12-3-ai-にインタビュー記録を整理させる" tabindex="-1">12.3 AI にインタビュー記録を整理させる <a class="header-anchor" href="#_12-3-ai-にインタビュー記録を整理させる" aria-label="Permalink to “12.3 AI にインタビュー記録を整理させる”">​</a></h3><p>インタビューが終わった後、最も起こりやすい問題は「情報がない」ことではなく、「情報が散らばっている」ことです。AI は断片的な会話を構造化されたメモに整理するのに非常に適しています：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>以下は 3 人のユーザーとのインタビュー記録です。</span></span>
<span class="line"><span>The Mom Test の観点から整理してください：</span></span>
<span class="line"><span>1. どの内容が事実で、どれがただの意見か</span></span>
<span class="line"><span>2. ユーザーの最近のリアルな行動は何か</span></span>
<span class="line"><span>3. 現在の代替ソリューションは何か</span></span>
<span class="line"><span>4. ユーザーがすでに払った時間、お金、または労力コストは何か</span></span>
<span class="line"><span>5. どの問題が繰り返し言及されたか</span></span>
<span class="line"><span>6. どの発言がポジティブに聞こえるが、証拠が不十分か</span></span></code></pre></div><p>このステップは特に価値があります。なぜなら、「良さそう」な内容と「本当に判断を支えられる」内容を分けるのに役立つからです。</p><p>簡単な入力は次のようなものです：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>あるユーザーとのインタビュー記録です：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- ツールがあれば試してみると言っていた</span></span>
<span class="line"><span>- 先週履歴書の修正に一晩かかった</span></span>
<span class="line"><span>- 今は主に友達に見てもらっている</span></span>
<span class="line"><span>- 一番難しいのは、どこまで直せば「応募できる」と言えるかわからないこと</span></span>
<span class="line"><span></span></span>
<span class="line"><span>意見と事実に分けてください。</span></span></code></pre></div><p>AI は次のように出力するかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>意見：</span></span>
<span class="line"><span>- ツールがあれば試してみる</span></span>
<span class="line"><span></span></span>
<span class="line"><span>事実：</span></span>
<span class="line"><span>- 先週履歴書の修正に一晩かかった</span></span>
<span class="line"><span>- 現在の代替ソリューションは友達に見てもらうこと</span></span>
<span class="line"><span>- 一番の難点は「いつ応募できるレベルになるかわからない」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ニーズ判断に使えるポイント：</span></span>
<span class="line"><span>- この問題は最近実際に発生した</span></span>
<span class="line"><span>- ユーザーはすでに明らかな時間コストを投入している</span></span>
<span class="line"><span>- 現在のソリューションは他人に依存し、不安定</span></span></code></pre></div><p>この出力は初心者に直感的に教えてくれます：どの言葉が判断に使えて、どの言葉は参考程度に聞いておけばいいか。</p><h3 id="_12-4-ai-に軽量なウェブ検索を先に行わせる" tabindex="-1">12.4 AI に軽量なウェブ検索を先に行わせる <a class="header-anchor" href="#_12-4-ai-に軽量なウェブ検索を先に行わせる" aria-label="Permalink to “12.4 AI に軽量なウェブ検索を先に行わせる”">​</a></h3><p>インタビューを始める前に、AI に少し軽い外部調査をさせることができます。例えば：</p><ul><li>公開コミュニティで、皆が最近この問題にどう不満を漏らしているか</li><li>既存ツールで最も批判されているのは何か</li><li>ユーザーがすでに似たような問題にお金を払っているかどうか</li><li>市場にどんな代替ソリューションがすでに存在するか</li></ul><p>この種の情報はリアルなインタビューに代わるものではありませんが、どこから質問を始めればいいかをより早く見つけるのに役立ちます。</p><p>例えば、簡単な入力は次のようなものです：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>調べてほしいことがあります：</span></span>
<span class="line"><span>「大学生が履歴書を修正する時に最もよく不満を漏らすこと」</span></span>
<span class="line"><span>最も一般的な不満を 5 つ、わかりやすい言葉でまとめて。</span></span></code></pre></div><p>AI は次のように出力するかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>よくある不満：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 履歴書に何を書けばいいかわからない</span></span>
<span class="line"><span>2. 職種ごとに書き換えるのが面倒</span></span>
<span class="line"><span>3. いくら修正しても十分かどうかわからない</span></span>
<span class="line"><span>4. 頼れる人に見てもらえない</span></span>
<span class="line"><span>5. いつまでも準備が終わらないと感じて先延ばしにする</span></span></code></pre></div><p>このような結果の価値は、インタビューの切り込み点を見つけやすくしてくれることにあります。</p><h3 id="_12-5-ai-に「インタビュー振り返りコーチ」をさせる" tabindex="-1">12.5 AI に「インタビュー振り返りコーチ」をさせる <a class="header-anchor" href="#_12-5-ai-に「インタビュー振り返りコーチ」をさせる" aria-label="Permalink to “12.5 AI に「インタビュー振り返りコーチ」をさせる”">​</a></h3><p>インタビューが終わったばかりの記録を AI に渡して、改善点を指摘させることもできます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>以下は私のユーザーインタビュー記録の一部です。</span></span>
<span class="line"><span>The Mom Test の観点から振り返りを行ってください：</span></span>
<span class="line"><span>1. どの質問が承認を求めるような聞き方だったか</span></span>
<span class="line"><span>2. どの質問に明らかな誘導があったか</span></span>
<span class="line"><span>3. どこでさらに事実について掘り下げられたか</span></span>
<span class="line"><span>4. もう一度やるとしたら、この会話はどう聞けばよかったか</span></span></code></pre></div><p>これは初心者に特に役立ちます。なぜなら、「私は証拠を集めているのか、それとも励ましを集めているのか」という感度をより早く構築できるからです。</p><h2 id="📚-課題" tabindex="-1">📚 課題 <a class="header-anchor" href="#📚-課題" aria-label="Permalink to “📚 課題”">​</a></h2><p>上記の内容に基づいて、次の課題を完了してください：</p><ol><li>最近やりたいプロダクトの方向性を一つ選び、本来聞こうとしていた「聞きづらい」質問を 5 つ書く</li><li>この 5 つの質問を The Mom Test スタイルに合わせて書き直す</li><li>潜在ユーザー 3 人に聞き、「前回この問題に直面したのはいつですか」を少なくとも 1 回は聞き出す</li><li>インタビュー終了後、4 種類の情報を整理する：リアルな行動、代替ソリューション、すでに払ったコスト、繰り返し出現した困難</li></ol><h2 id="さらに学ぶために" tabindex="-1">さらに学ぶために <a class="header-anchor" href="#さらに学ぶために" aria-label="Permalink to “さらに学ぶために”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">The Mom Test 公式サイト</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick: The Mom Test</a></li></ul>`,185))])}}});export{u as __pageData,m as default};
